CREATE TABLE finance_transaction_tag (id UUID PRIMARY KEY DEFAULT uuid_v7(),transaction_id UUID NOT NULL,tag_id UUID NOT NULL,ledger_id UUID NOT NULL,owner_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(transaction_id) REFERENCES finance_transaction(id),FOREIGN KEY(tag_id) REFERENCES finance_tag(id),FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),UNIQUE(transaction_id,tag_id)); CREATE INDEX idx_finance_transaction_tag ON finance_transaction_tag(tag_id,transaction_id);
